analyze.mjs.text:
// Classifies the result of one introspection probe (a real HTTP response,
// collected by probe.mjs's live network request, or pasted in by hand from
// the CLI's `--json` output) into an introspection-exposure report.
//
// Pure function, no I/O, no network -- this is the module both the CLI
// (check.mjs, which sends the real request) and the browser page
// (index.html, which either sends the same request itself when the target's
// CORS policy allows it, or renders a report from JSON pasted in) import, so
// the classification logic exists exactly once. See probe.mjs for why a
// browser can sometimes run this check directly and why the CLI exists for
// when it can't.
//
// The one finding this exists to raise: GraphQL's introspection meta-fields
// (`__schema`, `__type`) let any caller enumerate a server's entire schema --
// every query, every mutation, every type and field name, whether or not a
// real client ever links to it. OWASP's API Security guidance and GraphQL's
// own production-hardening docs both name disabling introspection in
// production as standard practice, precisely because it hands an
// unauthenticated caller a map of the API's full write surface (mutations)
// before they have to guess a single field name. A name match against a
// list of sensitive-sounding words is a hint to review by hand, never proof
// of a missing authorization check -- GraphQL field-level auth is common and
// this check has no way to see it.

const BUILTIN_SCALAR_NAMES = new Set(['String', 'Int', 'Float', 'Boolean', 'ID']);

const SENSITIVE_WORDS = [
  'admin', 'delete', 'remove', 'destroy', 'reset', 'password', 'secret',
  'token', 'impersonate', 'grant', 'role', 'permission', 'billing',
  'refund', 'payout', 'internal', 'debug', 'superuser', 'root', 'privilege',
  'apikey', 'credential', 'ban', 'suspend',
];

function looksSensitive(fieldName) {
  const lower = String(fieldName).toLowerCase();
  return SENSITIVE_WORDS.some((word) => lower.includes(word));
}

function fieldNames(rootType) {
  if (!rootType || !Array.isArray(rootType.fields)) return [];
  return rootType.fields.map((f) => f?.name).filter((n) => typeof n === 'string');
}

/**
 * @param {string} target - the endpoint URL that was probed (for display only)
 * @param {{ok: boolean, status: number|null, body: unknown, error: string|null, parseError?: string|null}} probe
 * @returns {{
 *   target: string, introspectionEnabled: boolean|null, incomplete: boolean,
 *   error: string|null, queryFieldCount: number, mutationFieldCount: number,
 *   subscriptionFieldCount: number, customTypeCount: number,
 *   queryFields: string[], mutationFields: string[], subscriptionFields: string[],
 *   findings: object[], dangerCount: number, noticeCount: number, ok: boolean,
 * }}
 */
export function buildReport(target, probe) {
  const empty = {
    target,
    queryFieldCount: 0, mutationFieldCount: 0, subscriptionFieldCount: 0, customTypeCount: 0,
    queryFields: [], mutationFields: [], subscriptionFields: [],
    findings: [], dangerCount: 0, noticeCount: 0,
  };

  if (!probe || probe.ok === false) {
    return { ...empty, introspectionEnabled: null, incomplete: true, error: probe?.error ?? 'no probe result', ok: false };
  }

  const body = probe.body;
  const schema = body && typeof body === 'object' ? body?.data?.__schema : null;

  if (!schema) {
    const errors = Array.isArray(body?.errors) ? body.errors : [];
    const introspectionBlockedExplicitly = errors.some((e) => /introspection/i.test(String(e?.message ?? '')));
    const noRecognisableBody = errors.length === 0 && !(body && typeof body === 'object' && 'data' in body);
    return {
      ...empty,
      introspectionEnabled: false,
      incomplete: noRecognisableBody,
      error: errors.length > 0
        ? errors.map((e) => e?.message).filter(Boolean).join('; ')
        : (probe.parseError ?? (noRecognisableBody ? 'response did not look like a GraphQL result (no "data" or "errors" key)' : null)),
      introspectionBlockedExplicitly,
      ok: !noRecognisableBody,
    };
  }

  const queryFields = fieldNames(schema.queryType);
  const mutationFields = fieldNames(schema.mutationType);
  const subscriptionFields = fieldNames(schema.subscriptionType);
  const types = Array.isArray(schema.types) ? schema.types : [];
  const customTypeCount = types.filter(
    (t) => t && typeof t.name === 'string' && !t.name.startsWith('__') && !BUILTIN_SCALAR_NAMES.has(t.name),
  ).length;

  const sensitiveMutations = mutationFields.filter(looksSensitive);
  const sensitiveQueries = queryFields.filter(looksSensitive);

  const findings = [];
  findings.push({
    id: 'introspection-enabled',
    severity: mutationFields.length > 0 ? 'danger' : 'notice',
    title: 'Introspection is enabled',
    detail:
      `This endpoint answered an unauthenticated introspection query with its schema: ` +
      `${queryFields.length} query field(s), ${mutationFields.length} mutation field(s), ` +
      `${subscriptionFields.length} subscription field(s), and ${customTypeCount} named type(s) ` +
      `in total. Anyone can enumerate every field, mutation, and type name this API exposes -- ` +
      `including ones no client ever links to -- which is the reconnaissance step OWASP's API ` +
      `Security guidance names as the reason to disable introspection in production.` +
      (mutationFields.length > 0 ? ' The mutation surface (write operations) is included.' : ''),
    evidence: `queryType.name=${schema.queryType?.name ?? '(none)'}, mutationType.name=${schema.mutationType?.name ?? '(none)'}`,
  });

  if (sensitiveMutations.length > 0) {
    findings.push({
      id: 'sensitive-mutation-names',
      severity: 'danger',
      title: `${sensitiveMutations.length} mutation name(s) look sensitive`,
      detail:
        `Mutation field name(s) matching common sensitive-operation wording: ${sensitiveMutations.join(', ')}. ` +
        `A name match is a hint to review by hand, not proof of a missing authorization check -- ` +
        `GraphQL field-level auth is common and this check cannot see it. Worth confirming each ` +
        `one actually enforces the privilege its name implies.`,
      evidence: `mutationType.fields: ${sensitiveMutations.join(', ')}`,
    });
  }
  if (sensitiveQueries.length > 0) {
    findings.push({
      id: 'sensitive-query-names',
      severity: 'notice',
      title: `${sensitiveQueries.length} query name(s) look sensitive`,
      detail:
        `Query field name(s) matching common sensitive-data wording: ${sensitiveQueries.join(', ')}. ` +
        `Same caveat as above -- a name match, not a confirmed access-control gap.`,
      evidence: `queryType.fields: ${sensitiveQueries.join(', ')}`,
    });
  }

  const dangerCount = findings.filter((f) => f.severity === 'danger').length;
  const noticeCount = findings.filter((f) => f.severity === 'notice').length;

  return {
    target,
    introspectionEnabled: true,
    incomplete: false,
    error: null,
    queryFieldCount: queryFields.length,
    mutationFieldCount: mutationFields.length,
    subscriptionFieldCount: subscriptionFields.length,
    customTypeCount,
    queryFields, mutationFields, subscriptionFields,
    findings,
    dangerCount, noticeCount,
    ok: dangerCount === 0,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: sends one real introspection-query POST to a GraphQL endpoint URL you
// name and reports whether introspection is enabled, and what it reveals.
// Your machine, your network -- no request goes through this portfolio or
// anywhere but the URL you pass.
//
//   node check.mjs <graphql-endpoint-url> [--json] [--timeout <ms>] [--header "Name: Value"]...
//
// This sends one ordinary, read-only POST -- GraphQL's introspection
// meta-fields cannot mutate anything -- and does nothing a GraphQL client
// wouldn't also do by querying the endpoint directly. Only point it at a
// system you own or are authorised to test, the same rule that applies to
// any request tool aimed at someone else's server.
//
// Exit code 0 when the probe completed and produced no danger-severity
// finding; 1 when a danger finding is present or the probe failed to
// complete (network error, timeout, bad URL, unrecognisable response).

import { sendIntrospectionQuery } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function parseArgs(argv) {
  const args = { target: null, json: false, timeoutMs: undefined, headers: {} };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') args.json = true;
    else if (argv[i] === '--timeout') args.timeoutMs = Number(argv[++i]);
    else if (argv[i] === '--header') {
      const raw = argv[++i] ?? '';
      const idx = raw.indexOf(':');
      if (idx > 0) args.headers[raw.slice(0, idx).trim()] = raw.slice(idx + 1).trim();
    } else if (!args.target && !argv[i].startsWith('--')) args.target = argv[i];
  }
  return args;
}

/** Pure orchestration: given a probe function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `probeFn` instead of hitting the network. Returns both the raw
 * `probe` and the derived `report` -- `--json` prints the raw probe (so the
 * browser page re-derives findings through the one classification function
 * it also imports, rather than trusting a second, possibly stale copy),
 * while text mode and the exit code use the report. */
export async function runCheck(target, { probeFn = sendIntrospectionQuery, timeoutMs, headers } = {}) {
  const probe = await probeFn(target, { timeoutMs, headers });
  const report = buildReport(target, probe);
  return { probe, report };
}

function formatText(report) {
  const lines = [];
  lines.push(`Target: ${report.target}`);
  lines.push('');

  if (report.incomplete) {
    lines.push(`Probe did not complete: ${report.error}. Re-run once the target is reachable.`);
  } else if (!report.introspectionEnabled) {
    lines.push('Introspection appears disabled or blocked -- the endpoint did not return a schema.');
    if (report.error) lines.push(`  server said: ${report.error}`);
  } else {
    lines.push(
      `Introspection is ENABLED: ${report.queryFieldCount} query field(s), ` +
        `${report.mutationFieldCount} mutation field(s), ${report.subscriptionFieldCount} subscription field(s), ` +
        `${report.customTypeCount} named type(s).`,
    );
    lines.push('');
    for (const f of report.findings) {
      const mark = f.severity === 'danger' ? '!!' : '--';
      lines.push(`${mark} [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push('');
    }
  }

  lines.push(
    'This is evidence from one response, not a full security assessment -- ' +
      'see README.md for what this tool does and does not check.',
  );
  return lines.join('\n');
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.target) {
    console.error('Usage: node check.mjs <graphql-endpoint-url> [--json] [--timeout <ms>] [--header "Name: Value"]');
    process.exit(2);
  }
  try {
    // eslint-disable-next-line no-new
    new URL(args.target);
  } catch {
    console.error(`Not a valid URL: ${args.target}`);
    process.exit(2);
  }

  const { probe, report } = await runCheck(args.target, { timeoutMs: args.timeoutMs, headers: args.headers });

  if (args.json) {
    console.log(JSON.stringify({ target: args.target, probe }, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Sends the one real HTTP request this check depends on: a POST carrying a
// deliberately minimal introspection query (root type names and their field
// names, plus every named type and its kind -- not the full recursive schema
// with arguments, descriptions, deprecations, and interfaces) to a GraphQL
// endpoint URL you name. Uses the global `fetch`, deliberately, so this exact
// module runs unmodified from the CLI (Node 22's built-in fetch) and, when a
// target's own CORS policy allows it, directly from the browser page too.
//
// That "when allowed" is the real difference from ventures/cors-misconfig-check:
// this request needs no forbidden header -- Origin is never set by us, only
// an ordinary POST with a JSON body -- so a target whose GraphQL endpoint sets
// a permissive CORS policy (common: many public GraphQL APIs are designed to
// be called from arbitrary frontends) lets a visitor's own browser tab run
// this exact check with no server of ours in the middle. A target that does
// not is why check.mjs exists: fetch() from Node enforces no CORS policy at
// all -- CORS is a browser-only restriction -- so the CLI always gets a real
// answer regardless of the target's CORS headers, at the cost of needing the
// visitor to run it themselves rather than typing a URL into the page.
//
// This module only ever talks to the one endpoint URL a caller names, using
// only the headers that same caller supplies. The query it sends is
// read-only by construction -- GraphQL's introspection meta-fields
// (`__schema`, `__type`) cannot mutate anything -- and it reads no local
// files and makes no other network call.

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'graphql-introspection-exposure-check/1 (+https://duncan-haywood.github.io/monorepo-projects/graphql-introspection-exposure-check/)';

// Deliberately narrower than a client library's full introspection query:
// no arguments, no descriptions, no deprecations, no interfaces/possible
// types. Enough to prove introspection is enabled and to name every root
// field and named type -- the evidence this check reports -- without pulling
// a potentially very large schema document across the wire.
export const INTROSPECTION_QUERY = `query GraphQLIntrospectionExposureCheck {
  __schema {
    queryType { name fields { name } }
    mutationType { name fields { name } }
    subscriptionType { name fields { name } }
    types { name kind }
  }
}`;

/**
 * @param {string} endpointUrl
 * @param {{headers?: Record<string,string>, timeoutMs?: number, fetchImpl?: Function}} [opts]
 * @returns {Promise<{ok: boolean, status: number|null, body: unknown, error: string|null, parseError: string|null}>}
 *   `ok` is transport-level: true whenever a response was received at all,
 *   even a 4xx/5xx one -- a GraphQL server commonly answers a blocked
 *   introspection query with an ordinary error body rather than a network
 *   failure, and that is informative, not a failure to report as one.
 */
export async function sendIntrospectionQuery(endpointUrl, { headers = {}, timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl } = {}) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (typeof doFetch !== 'function') {
    return { ok: false, status: null, body: null, error: 'no fetch implementation available in this environment', parseError: null };
  }

  let url;
  try {
    url = new URL(endpointUrl);
  } catch (err) {
    return { ok: false, status: null, body: null, error: `invalid URL: ${err.message}`, parseError: null };
  }
  if (url.protocol !== 'https:' && url.protocol !== 'http:') {
    return { ok: false, status: null, body: null, error: `unsupported scheme: ${url.protocol}`, parseError: null };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await doFetch(url.toString(), {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        accept: 'application/json',
        'user-agent': USER_AGENT,
        ...headers,
      },
      body: JSON.stringify({ query: INTROSPECTION_QUERY, operationName: 'GraphQLIntrospectionExposureCheck' }),
      signal: controller.signal,
    });
    let body = null;
    let parseError = null;
    try {
      body = await res.json();
    } catch (err) {
      parseError = err.message ?? String(err);
    }
    return { ok: true, status: res.status, body, error: null, parseError };
  } catch (err) {
    return { ok: false, status: null, body: null, error: err.message ?? String(err), parseError: null };
  } finally {
    clearTimeout(timer);
  }
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// target endpoint URL, custom headers, or the pasted/fetched probe result --
// that is exactly the kind of thing that must not be transmitted anywhere,
// and this tool never reads it off the visitor's machine either.

const STORAGE_KEY = 'graphql-introspection-exposure-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters: opting out
// *removes* the counters, so a flag stored inside them would be deleted by
// the very act it records. `recordUsage` above consults it directly as well
// as taking the caller's argument.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem that
  // throws on a full quota skips the delete entirely, and the visitor gets
  // neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
